ValidationRule.errorConditionFormula:
AND(
     OR(
       AND(ISCHANGED(StageName),
           NOT(ISPICKVAL(PRIORVALUE(StageName),"Acquisition (Sell)")),
           ISPICKVAL(StageName, "Acquisition (Sell)")
       ),
       AND(ISNEW(),ISPICKVAL(StageName, "Acquisition (Sell)")
     )
   ),
   Not($Permission.QualifyOpp),
   Not($Permission.BypassValidations)
)
